<?php

declare(strict_types=1);

// The rules of the Thelia core, without its licence header: this module has its own LICENSE file.
// Run from a Thelia project: vendor/bin/php-cs-fixer fix --dry-run --diff --config=local/modules/PriceWatch/.php-cs-fixer.dist.php
$finder = PhpCsFixer\Finder::create()
    ->in(__DIR__)
    ->exclude(['vendor', 'node_modules', 'templates'])
    // Generated by module:generate:model.
    ->notPath(['#^Model/#'])
    ->name('*.php')
    ->ignoreDotFiles(true)
    ->ignoreVCS(true);

return (new PhpCsFixer\Config())
    ->setRiskyAllowed(true)
    ->setRules([
        '@PHP80Migration' => true,
        '@PHP80Migration:risky' => true,
        '@PHP81Migration' => true,
        '@PHP82Migration' => true,
        '@PHP83Migration' => true,
        '@Symfony' => true,
        '@Symfony:risky' => true,
        'yoda_style' => false,
        'declare_strict_types' => true,
    ])
    ->setFinder($finder);
